insert into public.budget_account_catalog(code,description) select distinct budget_account,'Importado desde Excel' from public.technical_projects where budget_account<>'' on conflict(code) do update set active=true,updated_at=now();
insert into public.procurement_process_catalog(code,description) select distinct procurement_process,'Importado desde Excel' from public.technical_projects where procurement_process<>'' on conflict(code) do update set active=true,updated_at=now();
insert into public.supplier_catalog(name,description) select distinct supplier_contractor,'Importado desde Excel' from public.technical_projects where supplier_contractor<>'' on conflict(name) do update set active=true,updated_at=now();
